SELECT jsonb_build_object( 'id',event.id::text,'kind',event.kind,'levelId',event.id_level,'userId',event.id_user, 'previousUserId',event.id_previous_user,'recordId',event.id_record, 'previousRecordId',event.id_previous_record,'payload',event.payload, 'occurredAt',to_char(event.occurred_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), 'level',CASE WHEN level.id IS NULL THEN NULL ELSE jsonb_build_object( 'id',level.id,'xxHash',level.xx_hash,'levelItems',jsonb_build_object('nodes', CASE WHEN item.id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object( 'name',item.name,'imageUrl',item.image_url,'workshopId',item.workshop_id::text, 'author',CASE WHEN author.id IS NULL THEN NULL ELSE jsonb_build_object('id',author.id, 'steamId',author.steam_id::text,'steamName',author.steam_name,'discordId',author.discord_id::text) END)) END), 'levelPoints',CASE WHEN points.id_level IS NULL THEN NULL ELSE jsonb_build_object( 'points',points.points,'rating',points.rating) END, 'personalBestGlobals',jsonb_build_object('totalCount',(SELECT count(*) FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb WHERE pb.id_level=level.id))) END, 'user',CASE WHEN actor.id IS NULL THEN NULL ELSE jsonb_build_object('id',actor.id,'steamId', actor.steam_id::text,'steamName',actor.steam_name,'discordId',actor.discord_id::text) END, 'previousUser',CASE WHEN previous_actor.id IS NULL THEN NULL ELSE jsonb_build_object( 'id',previous_actor.id,'steamId',previous_actor.steam_id::text,'steamName',previous_actor.steam_name, 'discordId',previous_actor.discord_id::text) END, 'record',CASE WHEN record.id IS NULL THEN NULL ELSE jsonb_build_object('id',record.id,'time',record.time, 'modVersion',record.mod_version) END, 'previousRecord',CASE WHEN previous_record.id IS NULL THEN NULL ELSE jsonb_build_object( 'id',previous_record.id,'time',previous_record.time,'modVersion',previous_record.mod_version) END) AS value FROM public.discord_activity_event event LEFT JOIN public.level ON level.id=event.id_level AND level.publicly_visible=true LEFT JOIN LATERAL (SELECT * FROM public.level_item source WHERE source.id_level=level.id AND source.deleted=false ORDER BY source.updated_at DESC,source.id DESC LIMIT 1) item ON true LEFT JOIN public."user" author ON author.steam_id=item.author_id LEFT JOIN public.level_points points ON points.id_level=level.id LEFT JOIN public."user" actor ON actor.id=event.id_user LEFT JOIN public."user" previous_actor ON previous_actor.id=event.id_previous_user LEFT JOIN (SELECT * FROM public.record WHERE record_eligible) record ON record.id=event.id_record LEFT JOIN (SELECT * FROM public.record WHERE record_eligible) previous_record ON previous_record.id=event.id_previous_record WHERE event.id>$1 AND (event.id_level IS NULL OR level.id IS NOT NULL) AND (event.id_record IS NULL OR record.id IS NOT NULL) AND (event.id_previous_record IS NULL OR previous_record.id IS NOT NULL) ORDER BY event.id LIMIT $2
